import app from 'flarum/admin/app';
import FormModal from 'flarum/common/components/FormModal';
import Button from 'flarum/common/components/Button';
export default class MassActionModal extends FormModal {
  get translationPrefix() {
    const {
      action,
      type,
      all
    } = this.attrs;
    const suffix = type === 'post' ? '_post' : '';
    return `walsgit-recycle-bin.admin.mass_${action}${all ? '_all' : ''}${suffix}_modal`;
  }
  className() {
    return 'MassActionModal Modal--small';
  }
  title() {
    return app.translator.trans(`${this.translationPrefix}.title`);
  }
  content() {
    return m("div", {
      className: "Modal-body"
    }, m("p", null, app.translator.trans(`${this.translationPrefix}.text_start`, {
      u: m("u", null)
    }), ' ', m("strong", null, this.attrs.all ? this.attrs.totalCount : this.attrs.selectedIds.size), ' ', app.translator.trans(`${this.translationPrefix}.text_end`)), m("div", {
      className: "Form-group"
    }, m(Button, {
      className: 'Button Button--primary Button--block',
      type: 'submit',
      loading: this.loading
    }, app.translator.trans(`${this.translationPrefix}.submit_button`))));
  }
  onsubmit(e) {
    e.preventDefault();
    this.loading = true;
    const {
      type,
      action,
      selectedIds,
      all
    } = this.attrs;
    app.request({
      method: 'POST',
      url: `${app.forum.attribute('apiUrl')}/recycle-bin/mass-${type}s`,
      body: {
        action,
        ...(all ? {
          all: true
        } : {
          ids: Array.from(selectedIds)
        })
      }
    }).then(() => {
      this.hide();
      this.attrs.onSuccess?.();
      m.redraw();
      app.alerts.show({
        type: 'success'
      }, app.translator.trans(`${this.translationPrefix}.success`));
    }).catch(error => {
      this.loaded();
      this.onerror(error);
    });
  }
}
flarum.reg.add('walsgit-recycle-bin', 'admin/components/MassActionModal', MassActionModal);